/**
 * Architecture — Split-Brain explanation.
 *
 * Awwwards technique: horizontal scrubbed reveal.
 * As you scroll through, each card pinned-reveals left-to-right via
 * ScrollTrigger.batch() with per-card clip-path animation.
 *
 * Layout: 1.3fr | 0.8fr | 1.3fr — System 1 / Bridge / System 2.
 * Varied widths prevent the "three identical cards" anti-pattern (impeccable ban).
 */

import { useRef, useEffect } from "react";
import gsap from "gsap";
import { ScrollTrigger } from "gsap/ScrollTrigger";

gsap.registerPlugin(ScrollTrigger);

export function Architecture() {
  const sectionRef = useRef<HTMLElement>(null);

  useEffect(() => {
    const prefersReduced =
      window.matchMedia("(prefers-reduced-motion: reduce)").matches;
    if (prefersReduced) return;

    const cards = sectionRef.current?.querySelectorAll("[data-reveal]") ?? [];

    // ScrollTrigger.batch: each card clips in from bottom as it enters viewport
    const st = ScrollTrigger.batch(cards, {
      onEnter: (batch) => {
        gsap.from(batch, {
          opacity: 0,
          y: 48,
          clipPath: "inset(10% 0% 10% 0%)",
          duration: 0.8,
          stagger: 0.12,
          ease: "power3.out",
          onStart: () => {
            gsap.set(batch, { clipPath: "inset(0% 0% 0% 0%)" });
          },
        });
      },
      onLeave: (batch) => {
        gsap.set(batch, { opacity: 1 });
      },
      start: "top 80%",
      once: true,
    });

    return () => {
      if (Array.isArray(st)) {
        st.forEach((s) => s.kill());
      }
    };
  }, []);

  return (
    <section
      id="architecture"
      ref={sectionRef}
      style={{
        padding: "var(--sp-section) var(--sp-xl)",
        background: "var(--c-canvas)",
      }}
    >
      <div style={{ maxWidth: "1200px", margin: "0 auto" }}>
        <div style={{ textAlign: "center", marginBottom: "var(--sp-3xl)" }}>
          <h2 className="display-lg">Two brains, one bridge</h2>
        </div>

        <div
          className="stack-cols-3"
          style={{
            display: "grid",
            gridTemplateColumns: "1.3fr 0.8fr 1.3fr",
            gap: "var(--sp-xl)",
            alignItems: "start",
          }}
        >
          {/* System 1 — wider */}
          <div
            data-reveal
            style={{
              background: "var(--c-system1-soft)",
              borderRadius: "var(--r-md)",
              padding: "var(--sp-xl)",
              color: "var(--c-system1-ink)",
              clipPath: "inset(0% 0% 0% 0%)", // initial — batch will animate from
            }}
          >
            <div style={{ marginBottom: "var(--sp-md)" }}>
              <span className="pill pill-system1">System 1</span>
            </div>
            <h3 className="display-md" style={{ marginBottom: "var(--sp-sm)" }}>
              On-Device
            </h3>
            <p
              style={{
                fontSize: "var(--fs-body)",
                lineHeight: "var(--lh-body)",
                marginBottom: "var(--sp-md)",
              }}
            >
              Gemini Nano 4 runs locally at $0 cost. It distills your active
              context into a ≤300 token packet, scrubs PII before anything
              touches the network, and calculates a friction score.
            </p>
            <ul
              style={{
                listStyle: "none",
                fontSize: "var(--fs-ui-sm)",
                color: "var(--c-system1-ink)",
                lineHeight: "2",
                padding: 0,
              }}
            >
              <li><CheckIcon /> PII Scrubber — 9 pattern types</li>
              <li><CheckIcon /> Context Packet builder</li>
              <li><CheckIcon /> Friction Score calculator</li>
              <li><CheckIcon /> Offline queue manager</li>
            </ul>
          </div>

          {/* Corpus Callosum — narrower */}
          <div
            data-reveal
            style={{
              background: "var(--c-surface)",
              borderRadius: "var(--r-md)",
              padding: "var(--sp-xl)",
              boxShadow: "var(--shadow-card)",
              clipPath: "inset(0% 0% 0% 0%)",
            }}
          >
            <div style={{ marginBottom: "var(--sp-md)" }}>
              <span className="pill pill-idle">Bridge</span>
            </div>
            <h3 className="display-md" style={{ marginBottom: "var(--sp-sm)" }}>
              Corpus Callosum
            </h3>
            <p
              style={{
                fontSize: "var(--fs-body)",
                lineHeight: "var(--lh-body)",
                marginBottom: "var(--sp-md)",
                color: "var(--c-ink-secondary)",
              }}
            >
              Firebase AI Logic acts as the router. When friction exceeds the
              Remote Config threshold, it escalates from local to cloud —
              secured by App Check at every step.
            </p>
            <ul
              style={{
                listStyle: "none",
                fontSize: "var(--fs-ui-sm)",
                color: "var(--c-ink-secondary)",
                lineHeight: "2",
                padding: 0,
              }}
            >
              <li><ArrowIcon /> Remote Config — threshold 0.75</li>
              <li><ArrowIcon /> App Check enforcement</li>
              <li><ArrowIcon /> Firestore cross-device sync</li>
              <li><ArrowIcon /> Seamless cloud fallback</li>
            </ul>
          </div>

          {/* System 2 — wider */}
          <div
            data-reveal
            style={{
              background: "var(--c-system2-soft)",
              borderRadius: "var(--r-md)",
              padding: "var(--sp-xl)",
              color: "var(--c-system2-ink)",
              clipPath: "inset(0% 0% 0% 0%)",
            }}
          >
            <div style={{ marginBottom: "var(--sp-md)" }}>
              <span className="pill pill-system2">System 2</span>
            </div>
            <h3 className="display-md" style={{ marginBottom: "var(--sp-sm)" }}>
              Cloud
            </h3>
            <p
              style={{
                fontSize: "var(--fs-body)",
                lineHeight: "var(--lh-body)",
                marginBottom: "var(--sp-md)",
              }}
            >
              Cloud Gemini wakes only when needed. It receives the scrubbed
              context packet plus the last 5 context nodes from Firestore to
              produce deep cross-device synthesis.
            </p>
            <ul
              style={{
                listStyle: "none",
                fontSize: "var(--fs-ui-sm)",
                color: "var(--c-system2-ink)",
                lineHeight: "2",
                padding: 0,
              }}
            >
              <li><BoltIcon /> Deep reasoning on demand</li>
              <li><BoltIcon /> Cross-device context merge</li>
              <li><BoltIcon /> Only fires above threshold</li>
              <li><BoltIcon /> Manual trigger — Alt+Shift+C</li>
            </ul>
          </div>
        </div>
      </div>
    </section>
  );
}

/* ── Inline SVG icons ── */

function CheckIcon() {
  return (
    <svg
      width="14" height="14" viewBox="0 0 14 14" fill="none"
      style={{ display: "inline-block", verticalAlign: "-2px", marginRight: "var(--sp-xs)" }}
      aria-hidden="true"
    >
      <path d="M2 7.5L5.5 11L12 3.5" stroke="currentColor" strokeWidth="1.5" strokeLinecap="round" strokeLinejoin="round" />
    </svg>
  );
}

function ArrowIcon() {
  return (
    <svg
      width="14" height="14" viewBox="0 0 14 14" fill="none"
      style={{ display: "inline-block", verticalAlign: "-2px", marginRight: "var(--sp-xs)" }}
      aria-hidden="true"
    >
      <path d="M2 7H12M12 7L8 3M12 7L8 11" stroke="currentColor" strokeWidth="1.5" strokeLinecap="round" strokeLinejoin="round" />
    </svg>
  );
}

function BoltIcon() {
  return (
    <svg
      width="14" height="14" viewBox="0 0 14 14" fill="none"
      style={{ display: "inline-block", verticalAlign: "-2px", marginRight: "var(--sp-xs)" }}
      aria-hidden="true"
    >
      <path d="M8 1L3 8H7L6 13L11 6H7L8 1Z" stroke="currentColor" strokeWidth="1.5" strokeLinecap="round" strokeLinejoin="round" />
    </svg>
  );
}
