/**
 * SandboxGrid — the 4-column Live Ecosystem Sandbox.
 * ui-ux-pro-max motion.csv row 2: gsap.quickTo() for card hover on multiple targets.
 */

import { useRef, useEffect } from "react";
import gsap from "gsap";
import { DesktopEditor } from "./DesktopEditor.tsx";
import { SidePanel } from "./SidePanel.tsx";
import { CorpusCallosumBridge } from "./CorpusCallosumBridge.tsx";
import { AndroidCompanion } from "./AndroidCompanion.tsx";

export function SandboxGrid() {
  const gridRef = useRef<HTMLDivElement>(null);

  useEffect(() => {
    const cols = gridRef.current?.querySelectorAll<HTMLElement>("[data-sandbox-col]");
    if (!cols || window.matchMedia("(prefers-reduced-motion: reduce)").matches) return;

    const cleanups: (() => void)[] = [];

    cols.forEach((col) => {
      const yTo = gsap.quickTo(col, "y", { duration: 0.3, ease: "power2.out" });

      const onEnter = () => {
        col.style.willChange = "transform";
        yTo(-3);
      };
      const onLeave = () => {
        yTo(0);
        // remove will-change after tween settles
        setTimeout(() => { col.style.willChange = ""; }, 350);
      };

      col.addEventListener("mouseenter", onEnter);
      col.addEventListener("mouseleave", onLeave);
      cleanups.push(() => {
        col.removeEventListener("mouseenter", onEnter);
        col.removeEventListener("mouseleave", onLeave);
        col.style.willChange = "";
        yTo(0);
      });
    });

    return () => cleanups.forEach((c) => c());
  }, []);

  return (
    <>
      {/* Global controls bar */}
      <div
        style={{
          display: "flex",
          alignItems: "center",
          justifyContent: "center",
          gap: "var(--sp-md)",
          marginBottom: "var(--sp-xl)",
        }}
      >
        <ForceOfflineToggle />
        <ManualTriggerButton />
      </div>

      {/* 4-column grid */}
      <div
        ref={gridRef}
        style={{
          display: "grid",
          gridTemplateColumns: "repeat(auto-fit, minmax(280px, 1fr))",
          gap: "var(--sp-xl)",
        }}
      >
        <div data-sandbox-col>
          <ColBadge n={1} />
          <DesktopEditor />
        </div>
        <div data-sandbox-col>
          <ColBadge n={2} />
          <SidePanel />
        </div>
        <div data-sandbox-col>
          <ColBadge n={3} />
          <CorpusCallosumBridge />
        </div>
        <div data-sandbox-col>
          <ColBadge n={4} />
          <AndroidCompanion />
        </div>
      </div>
    </>
  );
}

import { useSandbox } from "./sandbox-context.tsx";

function BoltIcon() {
  return (
    <svg width="14" height="14" viewBox="0 0 14 14" fill="none" style={{ display: "inline-block", verticalAlign: "-2px" }} aria-hidden="true">
      <path d="M8 1L3 8H7L6 13L11 6H7L8 1Z" stroke="currentColor" strokeWidth="1.5" strokeLinecap="round" strokeLinejoin="round" />
    </svg>
  );
}

function ForceOfflineToggle() {
  const { state, dispatch } = useSandbox();
  return (
    <button
      className="btn btn-ghost"
      onClick={() => dispatch({ type: "TOGGLE_OFFLINE" })}
      style={
        state.isOffline
          ? {
              background: "var(--c-system2)",
              color: "var(--c-on-system2)",
              borderColor: "var(--c-system2)",
            }
          : undefined
      }
    >
      {state.isOffline ? "● Force offline: ON" : "Force offline: OFF"}
    </button>
  );
}

function ManualTriggerButton() {
  const { dispatch } = useSandbox();
  return (
    <button
      className="btn btn-system2"
      onClick={() => dispatch({ type: "MANUAL_TRIGGER" })}
    >
      <BoltIcon /> Alt + Shift + C
    </button>
  );
}

/** Step badge — shows the pipeline step number (1–4) above each column */
function ColBadge({ n }: { n: number }) {
  return (
    <div style={{
      display: "flex",
      alignItems: "center",
      gap: "var(--sp-xs)",
      marginBottom: "var(--sp-sm)",
    }}>
      <span style={{
        display: "inline-flex",
        alignItems: "center",
        justifyContent: "center",
        width: "20px",
        height: "20px",
        borderRadius: "var(--r-pill)",
        background: "var(--c-hairline)",
        color: "var(--c-ink-secondary)",
        fontSize: "var(--fs-micro)",
        fontFamily: "var(--font-mono)",
        fontWeight: 600,
        fontVariantNumeric: "tabular-nums",
        flexShrink: 0,
      }}>
        {n}
      </span>
      <div style={{
        height: "1px",
        flex: 1,
        background: n < 4 ? "var(--c-hairline)" : "transparent",
      }} />
    </div>
  );
}
